		end := len(s)
		for end > 0 && isWS(s[end-1]) {
			end--
		}
		return s[:end]
	}
	skipWS := func(s string, pos int) int {
		for pos < len(s) && isWS(s[pos]) {
			pos++
		}
		return pos
	}
	parseString := func(s string, pos int) (string, int, bool) {
		if pos >= len(s) || s[pos] != '"' {
			return "", pos, false
		}
		var buf []byte
		i := pos + 1
		for i < len(s) {
			c := s[i]
			if c == '"' {
				return string(buf), i + 1, true
			}
			if c == '\\' {
				if i+1 >= len(s) {
					return "", pos, false
				}
				e := s[i+1]
				switch e {
				case 'n':
					buf = append(buf, '\n')
				case 't':
					buf = append(buf, '\t')
				case 'r':
					buf = append(buf, '\r')
				case 'b', 'f':
				case 'u':
					if i+5 >= len(s) {
						return "", pos, false
					}
					i += 4
				default:
					buf = append(buf, e)
				}
				i += 2
				continue
			}
			buf = append(buf, c)
			i++
		}
		return "", pos, false
	}
	skipValue := func(s string, pos int) (int, bool) {
		depth := 0
		i := pos
		for i < len(s) {
			c := s[i]
			if c == '"' {
				_, j, ok := parseString(s, i)
				if !ok {
					return pos, false
				}
				i = j
				continue
			}
			if c == '{' || c == '[' {
				depth++
			} else if c == '}' || c == ']' {
				if depth == 0 {
					break
				}
				depth--
			} else if c == ',' && depth == 0 {
				break
			}
			i++
		}
		if i == pos || depth != 0 {
			return pos, false
		}
		return i, true
	}
	parseJSON := func(s string) (map[string]string, bool) {
		strs := map[string]string{}
		i := skipWS(s, 0)
		if i >= len(s) || s[i] != '{' {
			return nil, false
		}
		i = skipWS(s, i+1)
		if i < len(s) && s[i] == '}' {
			i++
		} else {
			for {
				key, j, ok := parseString(s, i)
				if !ok {
					return nil, false
				}
				i = skipWS(s, j)
				if i >= len(s) || s[i] != ':' {
					return nil, false
				}
				i = skipWS(s, i+1)
				if i < len(s) && s[i] == '"' {
					v, j2, ok2 := parseString(s, i)
					if !ok2 {
						return nil, false
					}
					strs[key] = v
					i = j2
				} else {
					j2, ok2 := skipValue(s, i)
					if !ok2 {
						return nil, false
					}
					i = j2
				}
				i = skipWS(s, i)
				if i < len(s) && s[i] == ',' {
					i = skipWS(s, i+1)
					continue
				}
				if i < len(s) && s[i] == '}' {
					i++
					break
				}
				return nil, false
			}
		}
		if skipWS(s, i) != len(s) {
			return nil, false
		}
		return strs, true
	}
	parseOpen := func(line string) (string, string, regionMarker, bool) {
		i := 0
		for i < len(line) && isIndent(line[i]) {
			i++
		}
		rest := line[i:]
		var leader string
		switch {
		case len(rest) >= 2 && rest[0] == '/' && rest[1] == '/':
			leader = "//"
		case len(rest) >= 1 && rest[0] == '#':
			leader = "#"
		default:
			return "", "", regionMarker{}, false
		}
		pos := i + len(leader)
		const prefix = " sedum:"
		rest = line[pos:]
		if len(rest) < len(prefix) || rest[:len(prefix)] != prefix {
			return "", "", regionMarker{}, false
		}
		pos += len(prefix)
		rest = line[pos:]
		sp := -1
		for k := 0; k < len(rest); k++ {
			if rest[k] == ' ' {
				sp = k
				break
			}
		}
		if sp <= 0 {
			return "", "", regionMarker{}, false
		}
		action := rest[:sp]
		jsonStart := pos + sp + 1
		if jsonStart >= len(line) || line[jsonStart] != '{' {
			return "", "", regionMarker{}, false
		}
		strs, ok := parseJSON(trimRight(line[jsonStart:]))
		if !ok {
			return "", "", regionMarker{}, false
		}
		tier, ok1 := strs["tier"]
		record, ok2 := strs["record"]
		gen, ok3 := strs["gen"]
		pkg, ok4 := strs["pkg"]
		if !ok1 || !ok2 || !ok3 || !ok4 {
			return "", "", regionMarker{}, false
		}
		return leader, action, regionMarker{Tier: tier, Record: record, Gen: gen, Pkg: pkg, Prefix: line[:jsonStart]}, true
	}
	closes := func(line, leader, action string) bool {
		i := 0
		for i < len(line) && isIndent(line[i]) {
			i++
		}
		rest := line[i:]
		if len(rest) < len(leader)+1 || rest[:len(leader)] != leader || rest[len(leader)] != ' ' {
			return false
		}
		rest = rest[len(leader)+1:]
		want := "/sedum:" + action
		if len(rest) < len(want) || rest[:len(want)] != want {
			return false
		}
		return trimRight(rest[len(want):]) == ""
	}
	var lines []string
	start := 0
	for i := 0; i <= len(content); i++ {
		if i == len(content) || content[i] == '\n' {
			lines = append(lines, content[start:i])
			start = i + 1
		}
	}
	var out []string
	markers := []regionMarker{}
	inRegion := false
	var leader, action string
	var marker regionMarker
	var body string
	for _, line := range lines {
		if !inRegion {
			l, a, m, ok := parseOpen(line)
			if ok {
				inRegion = true
				leader, action, marker = l, a, m
				body = ""
				out = append(out, placeholder)
				continue
			}
			out = append(out, line)
			continue
		}
		if closes(line, leader, action) {
			inRegion = false
			marker.Body = body
			marker.Close = line
			markers = append(markers, marker)
			continue
		}
		if _, _, _, ok := parseOpen(line); ok {
			return "", nil, false
		}
		body += line + "\n"
	}
	if inRegion {
		return "", nil, false
	}
	var buf []byte
	for i, l := range out {
		if i > 0 {
			buf = append(buf, '\n')
		}
		buf = append(buf, l...)
	}
	return string(buf), markers, true
}

